export class PigeonParseError extends Error {
  readonly position: Position;
  readonly expected: string[];

  constructor(message: string, position: Position, expected: string[] = []) {
    super(message);
    this.name = "PigeonParseError";
    this.position = position;
    this.expected = expected;
  }
}

function clonePoint(point: Savepoint): Savepoint {
  return {
    line: point.line,
    col: point.col,
    offset: point.offset,
    index: point.index,
  };
}

function publicPosition(point: Savepoint): Position {
  return { line: point.line, col: point.col, offset: point.offset };
}

function utf8Width(codePoint: number): number {
  if (codePoint <= 0x7f) return 1;
  if (codePoint <= 0x7ff) return 2;
  if (codePoint <= 0xffff) return 3;
  return 4;
}

function lowerCodePoint(codePoint: number): number {
  const value = String.fromCodePoint(codePoint).toLowerCase();
  return value.codePointAt(0) as number;
}

